/**
 * split-reveal — un titular entra línea por línea (o palabra, o letra), cada
 * una subiendo desde atrás de su propia máscara. GSAP SplitText con `mask`,
 * `autoSplit` (re-parte al cargar fuentes o cambiar el ancho) y `aria`.
 * Familia: texto · Intensidad 2 · deps: gsap.
 *
 *   <h2 data-fx-split>Toda la sala en una mano</h2>
 *
 * Para que no se vea el texto antes de partir, ocultalo solo con JS y con una
 * salida si el script falla (se muestra a los 2,5 s igual):
 *
 *   .js [data-fx-split]:not([data-fx-ready]) { opacity: 0; animation: fx-show 0s 2.5s forwards; }
 *   @keyframes fx-show { to { opacity: 1; } }
 *
 * Reduced motion: el texto queda entero y visible (en vivo).
 * destroy(): SplitText.revert() devuelve el texto original y los tweens se matan.
 */

import { motionSwitch, preserve, type FxHandle } from '../../core/index';
import { SplitText } from 'gsap/SplitText';
import { fxGsap, HOUSE_EASE } from '../../lib/gsap';

export interface SplitRevealOptions {
  by?: 'lines' | 'words' | 'chars';
  /** Segundos por parte. */
  duration?: number;
  stagger?: number;
  /** 'view' espera a que entre en pantalla; 'load' arranca ya (para el hero). */
  trigger?: 'view' | 'load';
  /** Posición de ScrollTrigger para `view`. */
  start?: string;
  delay?: number;
}

export function createSplitReveal(
  el: HTMLElement,
  { by = 'lines', duration = 0.9, stagger = 0.08, trigger = 'view', start = 'top 85%', delay = 0 }: SplitRevealOptions = {},
): FxHandle {
  const { gsap } = fxGsap(SplitText);
  const restore = preserve(el, { attributes: ['data-fx-ready'] });

  const off = motionSwitch({
    full: () => {
      const ctx = gsap.context(() => {
        SplitText.create(el, {
          type: by === 'lines' ? 'lines' : `${by},lines`,
          mask: by,
          autoSplit: true,
          aria: 'auto',
          onSplit(self: { lines: Element[]; words: Element[]; chars: Element[] }) {
            el.setAttribute('data-fx-ready', '');
            const parts = by === 'lines' ? self.lines : by === 'words' ? self.words : self.chars;
            return gsap.from(parts, {
              yPercent: 110,
              duration,
              stagger,
              delay,
              ease: HOUSE_EASE,
              ...(trigger === 'view' ? { scrollTrigger: { trigger: el, start, once: true } } : {}),
            });
          },
        });
      }, el);
      return () => ctx.revert();
    },
    reduced: () => {
      el.setAttribute('data-fx-ready', '');
    },
  });

  return {
    destroy() {
      off();
      restore();
    },
  };
}

'use client';

import type { DependencyList, RefObject } from 'react';
import { useFx } from '../../core/react';
import type { FxHandle } from '../../core/types';
import { createSplitReveal, type SplitRevealOptions } from './index';

/**
 * Hook de `split-reveal`. Monta sobre `ref.current` y destruye al desmontar.
 * Las opciones se leen al montar; pasá `deps` para volver a montar cuando cambien.
 */
export function useSplitReveal<E extends HTMLElement>(
  ref: RefObject<E | null>,
  options?: SplitRevealOptions,
  deps: DependencyList = [],
): RefObject<FxHandle | null> {
  return useFx(ref, (el) => createSplitReveal(el, options), deps);
}

/**
 * GSAP para los efectos del kit. Cada efecto registra solo los plugins que usa
 * (`fxGsap(SplitText)`), así un sitio que usa stacked-cards no carga SplitText
 * ni Flip. Todo lo que crea un efecto va en un `gsap.context()`, y `revert()`
 * deja el DOM como estaba (contrato §2).
 *
 * GSAP es 100% gratis (incluidos SplitText, ScrollTrigger y Flip) desde 2025.
 */

import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

const registered = new Set<unknown>();

/** Registra ScrollTrigger y los plugins pedidos (una sola vez cada uno). */
export function fxGsap(...plugins: object[]) {
  if (typeof window !== 'undefined') {
    for (const plugin of [ScrollTrigger, ...plugins]) {
      if (registered.has(plugin)) continue;
      gsap.registerPlugin(plugin);
      registered.add(plugin);
    }
  }
  return { gsap, ScrollTrigger };
}

/** Curva de la casa como ease de GSAP (equivale a cubic-bezier(0.16, 1, 0.3, 1)). */
export const HOUSE_EASE = 'expo.out';
